function tLabels(i, topY, botY) { // número e nome dentro do desenho: ficam centrados a qualquer tamanho
  const nm = TAROT[i][0].toUpperCase(), long = nm.length > 13;
  return `<g font-family="Cinzel, 'Cormorant Garamond', serif" font-weight="700" fill="#2a1a04" text-anchor="middle"><text x="150" y="${topY}" font-size="17" dominant-baseline="central">${TAROT[i][1]}</text><text x="150" y="${botY}" font-size="${long ? 13.5 : 15.5}" letter-spacing="${long ? .3 : 1}" dominant-baseline="central"${nm.length > 17 ? ' textLength="170" lengthAdjust="spacingAndGlyphs"' : ''}>${nm}</text></g>`;
}
const tStar = (cx, cy, r, n = 5, k = .45, rot = -90) => { let d = ''; for (let i = 0; i < n * 2; i++) { const a = (rot + i * 180 / n) * Math.PI / 180, rr2 = i % 2 ? r * k : r; d += (i ? 'L' : 'M') + (cx + rr2 * Math.cos(a)).toFixed(1) + ',' + (cy + rr2 * Math.sin(a)).toFixed(1); } return `<path d="${d}Z"`; };
const tRays = (cx, cy, r1, r2, n, w, f, wavy) => { let s = ''; for (let i = 0; i < n; i++) { const a = i * 360 / n * Math.PI / 180, b = (i * 360 / n + w) * Math.PI / 180, c2 = (i * 360 / n - w) * Math.PI / 180, R = wavy && i % 2 ? r2 * .82 : r2; s += `<path d="M${cx + r1 * Math.cos(b)},${cy + r1 * Math.sin(b)}L${cx + R * Math.cos(a)},${cy + R * Math.sin(a)}L${cx + r1 * Math.cos(c2)},${cy + r1 * Math.sin(c2)}Z" fill="${f}"/>`; } return s; };
function svgClean(x) { // remove atributos repetidos (o último ganha): o SVG fica XML válido e as imagens partilhadas não saem em branco
  return x.replace(/<[a-zA-Z][^<>]*>/g, tag => { const seen = {}, parts = []; const re = /\s([a-zA-Z:-]+)="[^"]*"/g; let m, last = 0, head = tag.match(/^<[a-zA-Z]+/)[0]; const attrs = []; while ((m = re.exec(tag))) attrs.push([m[1], m[0]]); if (attrs.length === new Set(attrs.map(a => a[0])).size) return tag; const keep = new Map(); attrs.forEach(a => keep.set(a[0], a[1])); return head + [...keep.values()].join('') + (/\/>$/.test(tag) ? '/>' : '>'); });
}
