  ctx.textAlign = 'center'; ctx.fillStyle = '#f2c76e'; ctx.font = '700 36px Cinzel'; ctx.fillText('A MINHA CARTA DE HOJE', W / 2, 95);
  const g = ctx.createRadialGradient(W / 2, 520, 40, W / 2, 520, 420); g.addColorStop(0, 'rgba(255,230,150,.35)'); g.addColorStop(1, 'rgba(255,230,150,0)'); ctx.fillStyle = g; ctx.fillRect(0, 100, W, 860);
