  ctx.textAlign = 'center'; ctx.fillStyle = '#fff'; ctx.font = 'italic 600 44px "Cormorant Garamond"'; wrap(ctx, `«${TDAY[i][3]}»`, W / 2, 1015, W - 160, 54, 2, 'center');
  ctx.fillStyle = '#e8e1ff'; ctx.font = '500 30px Manrope'; wrap(ctx, TDAY[i][0], W / 2, 1150, W - 170, 42, 3, 'center');
